function branchPhones(value){
 const parts=String(value||'').split(/\s*[-–—/;,|\n]\s*/).filter(Boolean);
 const phones=[];let area='';
 for(const part of parts){
  let digits=part.replace(/\D/g,'');
  if(digits.startsWith('0090'))digits=digits.slice(2);
  if(/^90[2-5]\d{9}$/.test(digits))digits=digits.slice(2);
  else if(/^0[2-5]\d{9}$/.test(digits))digits=digits.slice(1);
  if(/^[2-5]\d{9}$/.test(digits)){area=digits.slice(0,3);phones.push('+90'+digits);}
  else if(/^\d{7}$/.test(digits)&&area){phones.push('+90'+area+digits);}
 }
 return [...new Set(phones)];
}
